const API_BASE=window.location.origin;const TOKEN_KEY='mftracker_access_token';const REFRESH_KEY='mftracker_refresh_token';const loadingState=document.getElementById('loadingState');const loginState=document.getElementById('loginState');const dashboardState=document.getElementById('dashboardState');const dashboardSkeleton=document.getElementById('dashboardSkeleton');const dashboardContent=document.getElementById('dashboardContent');const errorState=document.getElementById('errorState');document.addEventListener('DOMContentLoaded',()=>{checkAuth();setupEventListeners()});function setupEventListeners(){document.getElementById('loginForm').addEventListener('submit',handleLogin);document.getElementById('logoutBtn').addEventListener('click',handleLogout);document.getElementById('refreshAllNavBtn')?.addEventListener('click',refreshAllNav);document.getElementById('recalcXirrBtn')?.addEventListener('click',recalcXirr);document.getElementById('addFundBtn')?.addEventListener('click',()=>window.location.href='/dashboard/add-fund/');document.getElementById('retryBtn')?.addEventListener('click',loadDashboard)}function showState(state){loadingState.style.display=state==='loading'?'flex':'none';loginState.style.display=state==='login'?'flex':'none';dashboardState.style.display=state==='dashboard'?'block':'none';errorState.style.display=state==='error'?'block':'none'}async function checkAuth(){showState('loading');const accessToken=localStorage.getItem(TOKEN_KEY);const refreshToken=localStorage.getItem(REFRESH_KEY);if(!accessToken){showState('login');return}try{const response=await fetch(`${API_BASE}/api/dashboard/`,{headers:{'Authorization':`Bearer ${accessToken}`}});if(response.ok){loadDashboard()}else if(response.status===401){if(refreshToken){await refreshAccessToken()}else{clearTokens();showState('login')}}else{showState('error');document.getElementById('errorMessage').textContent='Failed to authenticate'}}catch(error){console.error('Auth check failed:',error);showState('dashboard');dashboardSkeleton.style.display='none';dashboardContent.style.display='block';document.getElementById('noHoldings').classList.remove('d-none')}}async function handleLogin(e){e.preventDefault();const username=document.getElementById('username').value;const password=document.getElementById('password').value;const loginBtn=document.getElementById('loginBtn');const loginError=document.getElementById('loginError');loginBtn.disabled=true;loginBtn.querySelector('.spinner-border').classList.remove('d-none');loginBtn.querySelector('.btn-text').textContent='Signing in...';loginError.classList.add('d-none');try{const response=await fetch(`${API_BASE}/api/token/`,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:`username=${encodeURIComponent(username)}&password=${encodeURIComponent(password)}`});const data=await response.json();if(response.ok){localStorage.setItem(TOKEN_KEY,data.access);localStorage.setItem(REFRESH_KEY,data.refresh);loadDashboard()}else{loginError.textContent=data.detail||'Login failed. Please check your credentials.';loginError.classList.remove('d-none');loginBtn.disabled=false;loginBtn.querySelector('.spinner-border').classList.add('d-none');loginBtn.querySelector('.btn-text').textContent='Sign In'}}catch(error){console.error('Login failed:',error);loginError.textContent='Network error. Please try again.';loginError.classList.remove('d-none');loginBtn.disabled=false;loginBtn.querySelector('.spinner-border').classList.add('d-none');loginBtn.querySelector('.btn-text').textContent='Sign In'}}async function refreshAccessToken(){const refreshToken=localStorage.getItem(REFRESH_KEY);try{const response=await fetch(`${API_BASE}/api/token/refresh/`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh:refreshToken})});const data=await response.json();if(response.ok){localStorage.setItem(TOKEN_KEY,data.access);loadDashboard()}else{clearTokens();showState('login')}}catch(error){console.error('Token refresh failed:',error);clearTokens();showState('login')}}function handleLogout(){clearTokens();showState('login')}function clearTokens(){localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(REFRESH_KEY)}async function loadDashboard(){showState('dashboard');dashboardSkeleton.style.display='block';dashboardContent.style.display='none';const accessToken=localStorage.getItem(TOKEN_KEY);try{const response=await fetch(`${API_BASE}/api/dashboard/`,{headers:{'Authorization':`Bearer ${accessToken}`}});if(response.ok){const data=await response.json();renderDashboard(data);dashboardSkeleton.style.display='none';dashboardContent.style.display='block'}else if(response.status===401){await refreshAccessToken()}else{throw new Error('Failed to load dashboard')}}catch(error){console.error('Dashboard load failed:',error);dashboardSkeleton.style.display='none';dashboardContent.style.display='block';document.getElementById('noHoldings').classList.remove('d-none');document.getElementById('noHoldings').innerHTML=`<p class="text-muted"><i class="bi bi-info-circle me-2"></i>Dashboard API not yet available. <a href="/dashboard/">Visit legacy dashboard</a> or complete Priority 4 implementation.</p>`}}function renderDashboard(data){document.getElementById('totalInvested').textContent=formatCurrency(data.total_invested||0);document.getElementById('totalCurrent').textContent=formatCurrency(data.total_current||0);const totalGain=data.total_gain||0;const totalGainPct=data.total_gain_pct||0;const gainLossCard=document.getElementById('gainLossCard');document.getElementById('totalGain').textContent=`${totalGain>=0?'+':''}${formatCurrency(totalGain)}`;document.getElementById('totalGain').className=`stat-value ${totalGain>=0?'text-gain':'text-loss'}`;document.getElementById('totalGainPct').textContent=`${totalGain>=0?'+':''}${totalGainPct.toFixed(2)}%`;document.getElementById('totalGainPct').className=`stat-sub ${totalGain>=0?'text-gain':'text-loss'}`;gainLossCard.className=`stat-card ${totalGain>=0?'stat-card-gain':'stat-card-loss'}`;const portfolioXirr=data.portfolio_xirr;const xirrCard=document.getElementById('xirrCard');if(portfolioXirr!==null){document.getElementById('portfolioXirr').textContent=`${portfolioXirr>=0?'+':''}${portfolioXirr.toFixed(2)}%`;document.getElementById('portfolioXirr').className=`stat-value ${portfolioXirr>=0?'text-gain':'text-loss'}`;xirrCard.className=`stat-card ${portfolioXirr>=0?'stat-card-gain':''}`}else{document.getElementById('portfolioXirr').innerHTML='<span class="text-muted">—</span>';xirrCard.className='stat-card'}const holdings=data.holdings||[];const tbody=document.getElementById('holdingsTableBody');const noHoldings=document.getElementById('noHoldings');if(holdings.length===0){tbody.innerHTML='';noHoldings.classList.remove('d-none')}else{noHoldings.classList.add('d-none');tbody.innerHTML=holdings.map(h=>`<tr><td><div class="fw-bold">${h.fund_name}</div><small class="text-muted">${h.scheme_code}</small></td><td class="text-end">${formatCurrency(h.invested)}</td><td class="text-end">${formatCurrency(h.current)}</td><td class="text-end ${h.gain>=0?'text-gain':'text-loss'}">${h.gain>=0?'+':''}${formatCurrency(h.gain)}<br><small>${h.gain_pct>=0?'+':''}${h.gain_pct.toFixed(2)}%</small></td><td class="text-end ${h.xirr>=0?'text-gain':'text-loss'}">${h.xirr!==null?`${h.xirr>=0?'+':''}${h.xirr.toFixed(2)}%`:'—'}</td><td class="text-end"><a href="/dashboard/fund/${h.id}/" class="btn btn-sm btn-outline-primary">View</a></td></tr>`).join('')}}function formatCurrency(value){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(value)}async function refreshAllNav(){const accessToken=localStorage.getItem(TOKEN_KEY);const btn=document.getElementById('refreshAllNavBtn');btn.disabled=true;btn.innerHTML='<i class="bi bi-arrow-clockwise me-1"></i>Refreshing...';try{const response=await fetch(`${API_BASE}/api/refresh-nav/`,{method:'POST',headers:{'Authorization':`Bearer ${accessToken}`,'Content-Type':'application/json'}});if(response.ok){await loadDashboard()}else{alert('Failed to refresh NAV')}}catch(error){console.error('Refresh failed:',error);alert('Network error during refresh')}finally{btn.disabled=false;btn.innerHTML='<i class="bi bi-arrow-clockwise me-1"></i>Refresh All NAV'}}async function recalcXirr(){const accessToken=localStorage.getItem(TOKEN_KEY);const btn=document.getElementById('recalcXirrBtn');btn.disabled=true;btn.innerHTML='<i class="bi bi-arrow-clockwise me-1"></i>Recalculating...';try{const response=await fetch(`${API_BASE}/api/recalc-xirr/`,{method:'POST',headers:{'Authorization':`Bearer ${accessToken}`,'Content-Type':'application/json'}});if(response.ok){await loadDashboard()}else{alert('Failed to recalculate XIRR')}}catch(error){console.error('Recalc failed:',error);alert('Network error during recalculation')}finally{btn.disabled=false;btn.innerHTML='<i class="bi bi-arrow-clockwise me-1"></i>Recalc XIRR'}}
